c7=A.a(["\u062a\u0641\u062a\u062d \u0639\u0644\u0649 \u0643\u0644 \u0645\u0631\u0627\u0643\u0632\u0643\u060c \u0648\u062a\u062e\u062a\u0627\u0631 \u0645\u0631\u0643\u0632\u064b\u0627 (\u0628\u0641\u0631\u0648\u0639\u0647 \u0623\u0648 \u0648\u062d\u062f\u0647) \u0645\u0646 \u0627\u0644\u0634\u0631\u064a\u0637 \u062a\u062d\u062a \u0627\u0644\u0641\u062a\u0631\u0629","\u0648\u0643\u0630\u0644\u0643 \u0645\u0646 \u062f\u0627\u062e\u0644 \u0627\u0644\u0645\u0631\u0643\u0632: \u22ee \u0627\u0644\u0645\u0632\u064a\u062f \u2190 \u0627\u0644\u0627\u062e\u062a\u0628\u0627\u0631\u0627\u062a \u0627\u0644\u0645\u0646\u062c\u0632\u0629","\u0627\u062e\u062a\u0631 \u0627\u0644\u0641\u062a\u0631\u0629\u060c \u0641\u062a\u0638\u0647\u0631 \u0627\u0644\u062d\u0644\u0642\u0627\u062a \u0628\u0623\u0631\u0642\u0627\u0645\u0647\u0627 \u0648\u0627\u0644\u0641\u062a\u0631\u0629 \u0627\u0644\u0645\u0627\u0636\u064a\u0629 \u0644\u0644\u0645\u0642\u0627\u0631\u0646\u0629","\u0627\u0644\u062d\u0644\u0642\u0627\u062a \u0628\u0644\u0627 \u0627\u062e\u062a\u0628\u0627\u0631\u064d \u0645\u0637\u0648\u064a\u0651\u0629\u064c \u0622\u062e\u0631 \u0627\u0644\u0642\u0627\u0626\u0645\u0629\u060c \u0645\u0642\u0633\u0648\u0645\u0629\u064b \u0628\u0627\u0644\u062a\u0635\u0646\u064a\u0641: \u0623 + \u0628 \u062b\u0645 \u062c","\u062e\u0627\u0646\u0629 \u0627\u0644\u0628\u062d\u062b: \u0627\u0633\u0645 \u0627\u0644\u0645\u0639\u0644\u0651\u0645 \u0623\u0648 \u0627\u0644\u062d\u0644\u0642\u0629 \u0623\u0648 \u0627\u0644\u0637\u0627\u0644\u0628","\xab\u0641\u0631\u0632 \u062d\u0644\u0642\u0627\u062a \u0623 + \u0628\xbb: \u0627\u062e\u062a\u0628\u0627\u0631\u0627\u0646 \u0641\u0623\u0643\u062b\u0631 \xb7 \u0648\u0627\u062d\u062f \xb7 \u0628\u0644\u0627 \u0627\u062e\u062a\u0628\u0627\u0631 (\u0627\u0644\u0646\u0627\u062c\u062d \u0644\u0637\u0627\u0644\u0628\u064d \u0645\u0639\u062a\u0645\u062f)"],t4)
